-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): rockphysics.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/rockphysics.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   gas_class graded the Rutherford-Williams class as a number 1 to 4 (tol 0), a
--   one-in-four guess that the course names outright (module lesson slug
--   gas-is-class-three, capstone title 'flips the AVO class'). Replaced by the
--   largest absolute Shuey minus exact Zoeppritz error on the brine case over 0
--   to 40 degrees, the measured approximation gap advanced m04 teaches, read
--   from the AVO explorer tile at 6 dp.
--   RE-KEY gas_class (expected 3, tol 0)
--       -> brine_max_shuey_err 'Largest Shuey error, brine case, 0 to 40 deg' ratio, expected 0.005972095765271403, tol 0.0001
--   PROMPT was: the gas case's Rutherford-Williams class (as a number, 1 to 4),
--   PROMPT now: the largest absolute gap between Shuey and exact Zoeppritz on
--   the brine case over 0 to 40 degrees,
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: rockphysics/advanced.
-- Before it writes, the file counts academy_capstone_attempts on each and
-- REFUSES if any exist, unless D5 allowlists that tier with the exact attempt
-- ids (allowlist: empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- rockphysics / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 rockphysics refused: rockphysics/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'cf9e031824d1a413c3c49d6c73ba70d9' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "gas_class", "tol": 0, "unit": "class", "label": "Gas-case AVO class (1 to 4)", "expected": 3}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb then 'old'
              when md5(prompt) = '29275780598190d11bc93de24adcd976' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb then 'new'
              when md5(prompt) = '37f9c72d59288939d322371f9971e284' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w1 rockphysics refused: rockphysics/advanced matches neither its published form (prompt md5 cf9e031824d1a413c3c49d6c73ba70d9) nor its W1 form (prompt md5 29275780598190d11bc93de24adcd976), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 rockphysics: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 rockphysics refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'rockphysics' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'rockphysics/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'rockphysics/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 rockphysics refused: rockphysics/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 rockphysics: rockphysics/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 rockphysics refused: rockphysics/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Put the Ekene shale (vp 2743, vs 1394, rho 2450) over the SAND and screen both cases: the logged brine sand and its gas-substituted twin from the Professional tier. Report Shuey intercept and gradient for each, the largest absolute gap between Shuey and exact Zoeppritz on the brine case over 0 to 40 degrees, the exact Zoeppritz Rpp at 30 degrees for the gas case, and the wedge tuning thickness at 25 Hz.',
           fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb
     where app_slug = 'rockphysics' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 rockphysics refused: rockphysics/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '29275780598190d11bc93de24adcd976' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb)
        or (md5(prompt) = '37f9c72d59288939d322371f9971e284' and fields = '[{"key": "brine_intercept", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey intercept A", "expected": 0.03434399848203321}, {"key": "brine_gradient", "tol": 0.001, "unit": "ratio", "label": "Brine-case Shuey gradient B", "expected": -0.16766246414664518}, {"key": "gas_intercept", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey intercept A", "expected": -0.06282494068620303}, {"key": "gas_gradient", "tol": 0.001, "unit": "ratio", "label": "Gas-case Shuey gradient B", "expected": -0.2565633444602355}, {"key": "brine_max_shuey_err", "tol": 0.0001, "unit": "ratio", "label": "Largest Shuey error, brine case, 0 to 40 deg", "expected": 0.005972095765271403}, {"key": "zoep30", "tol": 0.001, "unit": "ratio", "label": "Exact Zoeppritz Rpp at 30 deg, gas", "expected": -0.12239091302671612}, {"key": "tuning_ms", "tol": 0, "unit": "ms", "label": "Wedge tuning thickness at 25 Hz", "expected": 16}]'::jsonb) from public.academy_capstones where app_slug = 'rockphysics' and tier = 'advanced' and active) is not true then
    raise exception 'w1 rockphysics refused: rockphysics/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 rockphysics: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
